<template><view class="association"><text>所属案件：{{currentTitle || '未关联'}}</text><picker :range="rows" range-key="title" :disabled="busy||disabled" @change="choose"><view class="button">选择已有案件</view></picker><button v-if="more" size="mini" :disabled="busy" @click="load(true)">更多案件</button><button size="mini" :disabled="busy||disabled" @click="creating=!creating">新建并关联</button><button v-if="selected" size="mini" :disabled="busy||disabled" @click="clear">解除关联</button><text v-if="selected" class="link" @click="open">查看案件 ›</text><view v-if="creating"><input v-model="newTitle" maxlength="200" placeholder="案件标题（必填）" placeholder-style="color:#606266;font-size:16px;"/><button :loading="busy" :disabled="busy||disabled||!newTitle.trim()" @click="create">创建并关联</button></view><text v-if="error" class="error" @click="load(false)">{{error}} · 点击重新加载</text></view></template>
<script>
import {caseApi} from '@/common/api/cases';
export default{props:{value:{type:String,default:''},sessionId:{type:[String,Number],default:''},disabled:{type:Boolean,default:false}},data(){return{selected:this.value,linked:'',rows:[],page:0,more:false,busy:false,error:'',creating:false,newTitle:''};},computed:{currentTitle(){const r=this.rows.find(r=>String(r.id)===this.selected);return r?r.title:this.selected;}},watch:{value(v){this.selected=v;},sessionId(){this.restore();}},mounted(){this.load(false);this.restore();},beforeDestroy(){this._disposed=true;},methods:{open(){uni.navigateTo({url:'/pages/cases/index?id='+encodeURIComponent(this.selected)});},async load(append=false){if(this.busy)return;this.busy=true;this.error='';try{const p=append?this.page+1:1,r=await caseApi(this.$request,'/list','GET',{pageNum:p,pageSize:20});if(this._disposed)return;const old=this.rows.find(r=>String(r.id)===this.selected);this.rows=append?this.rows.concat(r.rows):r.rows;if(old&&!this.rows.some(r=>String(r.id)===this.selected))this.rows.unshift(old);this.page=p;this.more=p*20<Number(r.total);}catch(e){this.error=e.message;}finally{this.busy=false;}},async restore(){const id=this.sessionId;this._version=(this._version||0)+1;const version=this._version;if(!id){this.selected=this.value;return;}try{const r=await this.$request('/system/session/'+id,'GET',{}, {'content-type':'application/json'});if(this._disposed||version!==this._version)return;if(r.code!==200)throw new Error(r.msg||'会话不可用');this.selected=this.linked=r.data.caseId?String(r.data.caseId):'';this.$emit('input',this.selected);if(this.selected&&!this.rows.some(r=>String(r.id)===this.selected)){const c=await caseApi(this.$request,'/'+this.selected);if(!this._disposed&&version===this._version)this.rows.unshift(c.data.caseInfo);}}catch(e){this.error=e.message;}},choose(e){this.selected=String(this.rows[Number(e.detail.value)].id);return this.apply();},clear(){this.selected='';return this.apply();},async apply(){if(this.busy||this.disabled)return;this.busy=true;this.error='';try{if(this.sessionId){if(this.selected)await caseApi(this.$request,'/'+this.selected+'/sessions','POST',{sessionId:this.sessionId});else if(this.linked)await caseApi(this.$request,'/'+this.linked+'/sessions/'+this.sessionId,'DELETE');}this.linked=this.selected;this.$emit('input',this.selected);}catch(e){this.selected=this.linked;this.error=e.message;}finally{this.busy=false;}},async create(){if(this.busy||!this.newTitle.trim())return;this.busy=true;this.error='';try{const title=this.newTitle.trim(),r=await caseApi(this.$request,'','POST',{title,status:'进行中'});this.rows.unshift({id:String(r.data),title});this.selected=String(r.data);this.creating=false;this.newTitle='';this.busy=false;await this.apply();}catch(e){this.error=e.message;}finally{this.busy=false;}}}};
</script>
<style scoped>.association{padding:24rpx;background:#fff;border-radius:16rpx;margin:20rpx 0;font-size:16px}.association>text{display:block;margin:12rpx 0}.association button{font-size:14px;margin:12rpx 8rpx 0 0}.button,.link{color:var(--brand-link);padding:14rpx 0}.error{color:var(--brand-danger)}input{padding:20rpx;background:var(--brand-background)}</style>

<style scoped lang="scss">
@import '@/common/form-controls.scss';
input { @include native-input-frame; border:1px solid var(--brand-border); }
</style>
